(7697712, 1262783, 4008, '<td valign="top">Blurring a background does not make it miniature. If you do blur, it should be done much more gradually.</td>', 'Blurring a background does not make it miniature. If you do blur, it should be done much more gradually.', '2021-07-19 10:02:32.000000', NULL, 1),
(7697713, 1262896, 4008, '<td valign="top">The person in the mirror is drawing attention away from the two girls.</td>', 'The person in the mirror is drawing attention away from the two girls.', '2021-07-19 10:04:38.000000', NULL, 1),
(7697714, 1262884, 4008, '<td valign="top">Impressive. Shows how small and vulnerable people are in nature.</td>', 'Impressive. Shows how small and vulnerable people are in nature.', '2021-07-19 10:05:48.000000', NULL, 1),
(7697800, 1262890, 3306, '<td valign="top">Fantastic colors and detail on this extreme macro. Great capture.</td>', 'Fantastic colors and detail on this extreme macro. Great capture.', '2021-07-21 07:38:48.000000', NULL, 1),
(7697801, 1262747, 3306, '<td valign="top">Awesome composition. Ribbon worthy!</td>', 'Awesome composition. Ribbon worthy!', '2021-07-21 07:39:25.000000', NULL, 1),
(7697802, 1262768, 3306, '<td valign="top">Cute scene and very well devised. The characters help to emphasize the mini nature of the composition and who, of course would miss Mini Mouse:)!</td>', 'Cute scene and very well devised. The characters help to emphasize the mini nature of the composition and who, of course would miss Mini Mouse:)!', '2021-07-21 07:42:35.000000', NULL, 1),
